  tlen = (title != NULL) ? strlen(title) + 1 : 0;
  blen = (body  != NULL) ? strlen(body)  + 1 : 0;

  if (off + tlen + blen > UI_RPMSG_MAX_PAYLOAD)
    {
      /* Truncate body first, then title, keeping both NUL-terminated. */
      size_t room = UI_RPMSG_MAX_PAYLOAD - off;
      if (tlen > room)
