    {
      memcpy(m.payload + off, title, tlen);
    }
  if (blen > 0)
    {
      memcpy(m.payload + off + tlen, body, blen);
    }
  m.payload_len = (uint16_t)(off + tlen + blen);

  (void)ui_rpmsg_send(&m);
}

#endif /* CONFIG_AI_AGENT_UI_RPMSG */

