69	static int ui_rpmsg_server_rx(struct rpmsg_endpoint *ept, void *data,
70	                               size_t len, uint32_t source, void *priv)
71	{
72	  const struct ui_rpmsg_msg *m = data;
73	  size_t need;
74	
75	  (void)ept;
76	  (void)source;
77	  (void)priv;
78	
79	  if (len < 4)  /* header = op + reserved + payload_len */
80	    {
81	      return -EINVAL;
82	    }
83	
84	  need = 4 + (size_t)m->payload_len;
85	  if (len < need)
86	    {
87	      syslog(LOG_WARNING, "[%s] short msg op=%u len=%zu need=%zu\n",
88	             TAG, m->op, len, need);
89	      return -EINVAL;
90	    }
91	
92	  switch (m->op)
93	    {
94	      case UI_RPMSG_INIT:
95	        (void)lvgl_ui_channel_init();
96	        break;
97	
98	      case UI_RPMSG_START:
99	        (void)lvgl_ui_channel_start();
100	        break;
101	
102	      case UI_RPMSG_STOP:
103	        lvgl_ui_channel_stop();
104	        break;
105	
106	      case UI_RPMSG_SHOW:
107	        lvgl_ui_channel_show();
108	        break;
109	
110	      case UI_RPMSG_SEND:
111	        {
112	          /* Wire text is len-prefixed, not NUL-terminated. */
113	          char text[UI_RPMSG_MAX_TEXT + 1];
114	          size_t tl = m->payload_len;
115	          if (tl > UI_RPMSG_MAX_TEXT)
116	            {
117	              tl = UI_RPMSG_MAX_TEXT;
118	            }
119	          memcpy(text, m->payload, tl);
120	          text[tl] = '\0';
121	          /* Real CP send(): builds the bubble + voice_channel_speak()
122	             (no-op stub here).  Audio is handled on the AP side. */
123	          (void)lvgl_ui_channel_send(text);
124	        }
125	        break;
126	
127	      case UI_RPMSG_TOAST:
128	        {
129	          if (m->payload_len < 2 * sizeof(uint32_t))
130	            {
131	              break;
132	            }
133	          uint32_t bar_color;
134	          uint32_t duration_ms;
135	          memcpy(&bar_color,  m->payload + 0, sizeof(uint32_t));
136	          memcpy(&duration_ms, m->payload + 4, sizeof(uint32_t));
137	
138	          const char *title = (const char *)(m->payload + 8);
139	          size_t avail = m->payload_len - 8;
140	          /* title is NUL-terminated within the wire payload. */
141	          size_t tlen = strnlen(title, avail);
142	          const char *body = "";
143	          if (tlen < avail)
144	            {
145	              body = title + tlen + 1;  /* skip the NUL after title */
146	            }
147	          lvgl_toast_show_async(title, body, bar_color, duration_ms);
148	        }
149	        break;
150	
151	      default:
152	        syslog(LOG_WARNING, "[%s] unknown op %u\n", TAG, m->op);
153	        break;
154	    }
155	
156	  return 0;
157	}
