199: /**
200:  * Copy text into a fixed buffer with UTF-8-aware truncation.  Copies at most
201:  * dst_size-1 bytes, then if the cut lands inside a multi-byte UTF-8 sequence
202:  * (leading byte 0xC0..0xF4 not followed by enough continuation bytes 0x80..0xBF),
203:  * trims back to the last complete character.  Always NUL-terminates.
204:  *
205:  * This prevents a half-cut Chinese char from rendering as a replacement glyph
206:  * at the end of a truncated Agent reply.
207:  */
208: static void chat_view_copy_text(char* dst, const char* src, size_t dst_size)
209: {
210:     if (dst_size == 0) return;
211:     size_t n = strnlen(src, dst_size - 1);
212:     memcpy(dst, src, n);
213:     dst[n] = '\0';
214: 
215:     /* If we filled the buffer, the last char may be incomplete.  Walk back
216:      * from the end to find a UTF-8 leading byte and check its expected length
217:      * against the remaining bytes. */
218:     if (n < dst_size - 1) return;          /* src fit fully, no truncation */
219:     size_t i = n;
220:     while (i > 0) {
221:         unsigned char c = (unsigned char)dst[i - 1];
222:         if ((c & 0xC0) != 0x80) break;     /* not a continuation byte */
223:         i--;
224:     }
225:     if (i == 0) return;                     /* all continuation bytes? give up */
226:     unsigned char lead = (unsigned char)dst[i - 1];
227:     size_t need;
228:     if      ((lead & 0x80) == 0x00) need = 1;   /* ASCII */
229:     else if ((lead & 0xE0) == 0xC0) need = 2;
230:     else if ((lead & 0xF0) == 0xE0) need = 3;
231:     else if ((lead & 0xF8) == 0xF0) need = 4;
232:     else { dst[i - 1] = '\0'; return; }         /* invalid lead, cut it */
233:     if (n - (i - 1) < need) {
234:         dst[i - 1] = '\0';                      /* incomplete seq, trim it */
235:     }
236: }
