773	   * screen or full row update.
774	   */
775	
776	  if (stride == row_size)
777	    {
778	      /* simpler case, we can just send the whole buffer */
779	
780	      ginfo("Using full screen/full row mode\n");
781	      jd9853_wrram(priv, buffer, rows * row_size, 0, 1);
