/* Ground-truth GRAM readback (no human eyes needed).  Wait for the LVGL
 * thread to flush, then open /dev/lcd0 and read back two corner regions.
 * If the pixels match the bg blue (0x4a90d9 ~ RGB565 0x4c9b) the panel
 * GRAM latched our writes — the display pipeline is complete end to end.
 * If they read 0x0000 the SPI write did not latch (panel/init issue). */
sleep(3);
do
  {
    int lfd = open("/dev/lcd0", O_RDONLY);
    if (lfd < 0)
      {
        syslog(LOG_WARNING, "[%s] gram readback: open /dev/lcd0 rc=%d\n",
               TAG, lfd);
        break;
      }

    /* Read a 4x4 block at top-left (should be pure bg) and one near the
     * PTT button area (center-ish). 2 bytes/px (RGB565), 4 cols => 8 B/row. */
    uint8_t buf[4 * 4 * 2];
    struct lcddev_area_s area;
    memset(&area, 0, sizeof(area));
    area.row_start = 0;   area.row_end = 3;
    area.col_start = 0;  area.col_end = 3;
    area.stride = 4 * 2;
    area.data = buf;
    int rc1 = ioctl(lfd, LCDDEVIO_GETAREA, (unsigned long)&area);

    memset(buf, 0, sizeof(buf));
    area.row_start = 100; area.row_end = 103;
    area.col_start = 100; area.col_end = 103;
    area.data = buf;
    int rc2 = ioctl(lfd, LCDDEVIO_GETAREA, (unsigned long)&area);

    /* Print first 4 pixels of each read as RGB565. */
    syslog(LOG_INFO, "[%s] GRAM readback TL rc=%d: %02x%02x %02x%02x "
          "%02x%02x %02x%02x (bg blue RGB565~4c9b)\n", TAG, rc1,
          buf[0],buf[1],buf[2],buf[3],buf[4],buf[5],buf[6],buf[7]);
    syslog(LOG_INFO, "[%s] GRAM readback (100,100) rc=%d: %02x%02x %02x%02x "
          "%02x%02x %02x%02x\n", TAG, rc2,
          buf[0],buf[1],buf[2],buf[3],buf[4],buf[5],buf[6],buf[7]);
    close(lfd);
  }
while (0);

