    lv_nuttx_lcd_t * lcd = disp->driver_data;
    int ret;

    lcd->area.row_start = area_p->y1;
    lcd->area.row_end = area_p->y2;
    lcd->area.col_start = area_p->x1;
    lcd->area.col_end = area_p->x2;
    lcd->area.data = (uint8_t *)color_p;
    ret = ioctl(lcd->fd, LCDDEVIO_PUTAREA, (unsigned long) & (lcd->area));
    if (s_flush_count < 40 || ret < 0)
      {
        syslog(LOG_INFO, "[lv_nuttx_lcd] flush #%d y[%d..%d] x[%d..%d] "
               "rc=%d\n", ++s_flush_count, area_p->y1, area_p->y2,
               area_p->x1, area_p->x2, ret);
      }
    else
      {
        s_flush_count++;
      }
    lv_display_flush_ready(disp);
}

