67	/* Monotonic-ish millisecond timestamp.  CLOCK_MONOTONIC is not enabled on
68	 * this board, so CLOCK_REALTIME is used; only differences matter here and
69	 * the epoch never changes at runtime, so it is safe for this purpose.
70	 */
71	
72	static int64_t now_ms(void)
73	{
74	  struct timespec ts;
75	
76	  clock_gettime(CLOCK_REALTIME, &ts);
77	  return (int64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
78	}
