/* M4 frame-rate probe: measure the LCDDEVIO_PUTAREA ioctl duration (SPI
 * throughput) and periodic flush rate.  Guarded by the first-40 + every-100
 * log pattern so steady-state stays quiet.  Remove after M4 settles. */
static int s_flush_count = 0;
static struct timespec s_rate_t0;

static void flush_cb(lv_display_t * disp, const lv_area_t * area_p,
                     uint8_t * color_p)
{
    lv_nuttx_lcd_t * lcd = disp->driver_data;
    int ret;
    struct timespec t0, t1;
    long us;

    lcd->area.row_start = area_p->y1;
    lcd->area.row_end = area_p->y2;
    lcd->area.col_start = area_p->x1;
    lcd->area.col_end = area_p->x2;
    lcd->area.data = (uint8_t *)color_p;

    clock_gettime(CLOCK_MONOTONIC, &t0);
    ret = ioctl(lcd->fd, LCDDEVIO_PUTAREA, (unsigned long) & (lcd->area));
    clock_gettime(CLOCK_MONOTONIC, &t1);

    us = (t1.tv_sec - t0.tv_sec) * 1000000 + (t1.tv_nsec - t0.tv_nsec) / 1000;

    if (s_flush_count == 0)
      s_rate_t0 = t0;

    if (s_flush_count < 40 || ret < 0)
      {
        int w = area_p->x2 - area_p->x1 + 1;
        int h = area_p->y2 - area_p->y1 + 1;
        syslog(LOG_INFO, "[lv_nuttx_lcd] flush #%d %dx%d rc=%d %ldus"
               " (%ld KB/s)\n", ++s_flush_count, w, h, ret, us,
               us > 0 ? (long)((w * h * 2) / us) : 0);
      }
    else
      {
        s_flush_count++;
      }

    /* Every 100 flushes: report the rolling flush rate. */
    if (s_flush_count >= 100 && (s_flush_count % 100) == 0)
      {
        long ms = (t1.tv_sec - s_rate_t0.tv_sec) * 1000
                + (t1.tv_nsec - s_rate_t0.tv_nsec) / 1000000;
        syslog(LOG_INFO, "[lv_nuttx_lcd] rate: %d flushes in %ldms"
               " (%.1f flush/s)\n", s_flush_count, ms,
               ms > 0 ? (float)s_flush_count * 1000.0f / ms : 0.0f);
        s_rate_t0 = t1;
      }

    lv_display_flush_ready(disp);
}
